//! Exercise the CLI and GeoTIFF round trip against the saved ArcGIS Pro 3.7
//! black-box probes, generated by scripts/research/blockops/probe.py.

use std::path::Path;
use std::process::Command;

use serde_json::Value;
use unigis_raster::{Compression, DataType, Raster, read_geotiff, write_geotiff};

fn compare(got: &Raster, want: &Value, case: &str) {
    let expected_type = match want["pixel"].as_str().unwrap() {
        "F32" => DataType::F32,
        "S32" => DataType::I32,
        other => panic!("unexpected probe pixel type {other}"),
    };
    assert_eq!(got.data_type, expected_type, "{case}");
    assert_eq!(got.bands.len(), 1, "{case}");
    assert_eq!(got.width as u64, want["cols"].as_u64().unwrap(), "{case}");
    assert_eq!(got.height as u64, want["rows"].as_u64().unwrap(), "{case}");
    let e = got.extent();
    for (g, w) in [e.0, e.1, e.2, e.3]
        .iter()
        .zip(want["extent"].as_array().unwrap())
    {
        assert!((g - w.as_f64().unwrap()).abs() < 1e-6, "{case}: extent");
    }
    assert_eq!(got.cell_width(), 90.0, "{case}");
    assert_eq!(got.cell_height(), 90.0, "{case}");
    // The JSON serializer rounds f32::MIN's decimal representation; compare
    // the actual pixel value rather than the extra f64 decimal digits.
    assert_eq!(
        got.nodata,
        want["nodata"].as_f64().map(|n| expected_type.store(n)),
        "{case}"
    );
    for (y, row) in want["values"].as_array().unwrap().iter().enumerate() {
        for (x, w) in row.as_array().unwrap().iter().enumerate() {
            let w = w.as_f64().unwrap();
            let g = got.get(x, y);
            if (w + 123_456_789.0).abs() < 10.0 {
                assert_eq!(g, None, "{case}: ({x}, {y})");
            } else {
                let g = g.unwrap_or_else(|| panic!("{case}: ({x}, {y}) unexpectedly NoData"));
                let tolerance = if expected_type.is_float() {
                    1e-5 * w.abs().max(1.0)
                } else {
                    0.0
                };
                assert!((g - w).abs() <= tolerance, "{case}: ({x}, {y}): {g} != {w}");
            }
        }
    }
}

#[test]
fn aggregate_cli_matches_arcgis() {
    let root = Path::new(env!("CARGO_MANIFEST_DIR")).join("../..");
    let reference: Value = serde_json::from_slice(
        &std::fs::read(root.join("testdata/arcgis-reference/blockops.json")).unwrap(),
    )
    .unwrap();
    let dir = std::env::temp_dir().join(format!("ug-aggregate-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let out = dir.join("out.tif");
    let mut checked = 0;
    for (tag, key, dtype) in [("f", "fl", DataType::F32), ("i", "it", DataType::I32)] {
        let rows = reference[key].as_array().unwrap();
        let height = rows.len();
        let width = rows[0].as_array().unwrap().len();
        let mut src = Raster::new(
            width,
            height,
            dtype,
            [
                500_000.0,
                30.0,
                0.0,
                5_000_000.0 + height as f64 * 30.0,
                0.0,
                -30.0,
            ],
        );
        src.nodata = Some(-9999.0);
        src.bands[0] = rows
            .iter()
            .flat_map(|r| r.as_array().unwrap().iter())
            .map(|v| dtype.store(v.as_f64().unwrap()))
            .collect();
        let input = dir.join(format!("{tag}.tif"));
        write_geotiff(&input, &src, Compression::None).unwrap();
        for stat in ["SUM", "MEAN", "MEDIAN", "MINIMUM", "MAXIMUM"] {
            for ignore in ["DATA", "NODATA"] {
                for (extent, suffix) in [("EXPAND", "exp"), ("TRUNCATE", "trunc")] {
                    let case = format!("agg_{tag}_{stat}_{ignore}_{suffix}");
                    let run = Command::new(env!("CARGO_BIN_EXE_ug"))
                        .arg("aggregate")
                        .arg(&input)
                        .arg(&out)
                        .arg("3")
                        .args([
                            "--aggregation-type",
                            stat,
                            "--ignore-nodata",
                            ignore,
                            "--extent-handling",
                            extent,
                        ])
                        .output()
                        .unwrap();
                    assert!(
                        run.status.success(),
                        "{case}: {}",
                        String::from_utf8_lossy(&run.stderr)
                    );
                    compare(&read_geotiff(&out).unwrap(), &reference[&case], &case);
                    checked += 1;
                }
            }
        }
        // Omitted options must reproduce SUM / EXPAND / DATA.
        let run = Command::new(env!("CARGO_BIN_EXE_ug"))
            .arg("aggregate")
            .arg(&input)
            .arg(&out)
            .arg("3")
            .output()
            .unwrap();
        assert!(
            run.status.success(),
            "{}",
            String::from_utf8_lossy(&run.stderr)
        );
        compare(
            &read_geotiff(&out).unwrap(),
            &reference[format!("agg_{tag}_SUM_DATA_exp")],
            "defaults",
        );

        // Refusal must leave no partial output (including a multiband raster).
        src.bands.push(src.bands[0].clone());
        let multi = dir.join("multi.tif");
        write_geotiff(&multi, &src, Compression::None).unwrap();
        for (input, args, message) in [
            (&input, vec!["1"], "invalid value"),
            (&input, vec!["2.5"], "invalid value"),
            (&input, vec!["18446744073709551615"], "invalid value"),
            (
                &input,
                vec!["3", "--aggregation-type", "RANGE"],
                "aggregation type",
            ),
            (
                &input,
                vec!["3", "--extent-handling", "OTHER"],
                "extent handling",
            ),
            (
                &input,
                vec!["3", "--ignore-nodata", "OTHER"],
                "ignore_nodata",
            ),
            (
                &input,
                vec!["20", "--extent-handling", "TRUNCATE"],
                "no output cells",
            ),
            (&multi, vec!["3"], "single-band"),
        ] {
            std::fs::remove_file(&out).unwrap_or(());
            let run = Command::new(env!("CARGO_BIN_EXE_ug"))
                .arg("aggregate")
                .arg(input)
                .arg(&out)
                .args(args)
                .output()
                .unwrap();
            assert!(!run.status.success());
            assert!(
                String::from_utf8_lossy(&run.stderr).contains(message),
                "{}",
                String::from_utf8_lossy(&run.stderr)
            );
            assert!(!out.exists(), "refused invocation created output");
        }
    }
    assert_eq!(checked, 40);
    std::fs::remove_dir_all(dir).unwrap();
}
